        var futures = new java.util.ArrayList<java.util.concurrent.Future<Integer>>();
        for (int i = 0; i < 8; i++) {
            futures.add(pool.submit(() -> call("POST", "/reservations", body(202, CPF, "2035-03-10", "2035-03-12", 2, "STANDARD")).status()));
